    listWakeTimeline: {
        parameters: {
            query?: {
                /** @description Only return rows with `at >= since` (RFC 3339). */
                since?: string;
                /** @description Max frames to return. Silently capped at 1000. */
                limit?: number;
            };
            header?: never;
            path: {
                /** @description App slug (lowercase, kebab-case; per-account unique). */
                slug: string;
                /**
                 * @description The per-wake correlation handle minted by the schedd
                 *     engine (UUID v4 in production). The endpoint returns
                 *     every `wake.*` events row whose `data.wake_id`
                 *     matches — the partial index `events_wake_id_idx`
                 *     (migrations/00113) serves the read in O(frames)
                 *     regardless of the events table size.
                 */
                wake_id: string;
            };
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description Wake-timeline frames. */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "wake_id": "abcdef01-2345-6789-abcd-ef0123456789",
                     *       "app_id": "0123456789abcdef0123456789abcdef",
                     *       "limit": 200,
                     *       "next_cursor": "",
                     *       "events": [
                     *         {
                     *           "at": "2026-07-25T13:25:00.123Z",
                     *           "kind": "wake.queue_accepted",
                     *           "actor": "schedd",
                     *           "data": {
                     *             "wake_id": "abcdef01-2345-6789-abcd-ef0123456789",
                     *             "app_id": "0123456789abcdef0123456789abcdef",
                     *             "request_id": "r-1",
                     *             "queue_wait_ms": 12
                     *           }
                     *         },
                     *         {
                     *           "at": "2026-07-25T13:25:00.135Z",
                     *           "kind": "wake.admitted",
                     *           "actor": "schedd",
                     *           "data": {
                     *             "wake_id": "abcdef01-2345-6789-abcd-ef0123456789",
                     *             "app_id": "0123456789abcdef0123456789abcdef",
                     *             "request_id": "r-1",
                     *             "account_id": "fdecba98-7654-3210-fedc-ba9876543210",
                     *             "plan": "pro"
                     *           }
                     *         },
                     *         {
                     *           "at": "2026-07-25T13:25:00.420Z",
                     *           "kind": "wake.boot_started",
                     *           "actor": "schedd",
                     *           "data": {
                     *             "wake_id": "abcdef01-2345-6789-abcd-ef0123456789",
                     *             "app_id": "0123456789abcdef0123456789abcdef",
                     *             "instance_id": "inst-1",
                     *             "node_id": "node-1",
                     *             "method": "restore"
                     *           }
                     *         },
                     *         {
                     *           "at": "2026-07-25T13:25:01.180Z",
                     *           "kind": "wake.readiness_200",
                     *           "actor": "vmmd",
                     *           "data": {
                     *             "wake_id": "abcdef01-2345-6789-abcd-ef0123456789",
                     *             "app_id": "0123456789abcdef0123456789abcdef",
                     *             "instance_id": "inst-1",
                     *             "node_id": "node-1",
                     *             "healthcheck_path": "/healthz",
                     *             "probe_count": 1,
                     *             "elapsed_ms": 760
                     *           }
                     *         },
                     *         {
                     *           "at": "2026-07-25T13:25:01.220Z",
                     *           "kind": "wake.proxy_first_byte",
                     *           "actor": "egress",
                     *           "data": {
                     *             "wake_id": "abcdef01-2345-6789-abcd-ef0123456789",
                     *             "app_id": "0123456789abcdef0123456789abcdef",
                     *             "request_id": "r-1",
                     *             "instance_id": "inst-1",
                     *             "node_id": "node-1",
                     *             "latency_ms": 40
                     *           }
                     *         }
                     *       ]
                     *     }
                     */
                    "application/json": components["schemas"]["WakeTimelineResponse"];
                };
            };
            /** @description Malformed query parameter on the wake-timeline read — `since` not RFC 3339 or `limit` out of range. */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/problem+json": components["schemas"]["Problem"];
                };
            };
            401: components["responses"]["Unauthorized"];
            /** @description No such app (slug) or wake_id is unknown. */
            404: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/problem+json": components["schemas"]["Problem"];
                };
            };
            429: components["responses"]["TooManyRequests"];
        };
    };
